set-variable.value:
@{
    try {
      if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
          || !context.Variables.ContainsKey("byokJwtValidated") || !(bool)context.Variables["byokJwtValidated"]
          || !context.Variables.ContainsKey("byokCallerAccountingMode") || (string)context.Variables["byokCallerAccountingMode"] != "jwt") { return "__invalid__"; }
      var method = (string)context.Variables["callerAuthMethod"];
      if (method != "entraJwt" && method != "oktaJwt") { return "__invalid__"; }
      var configuration = Newtonsoft.Json.Linq.JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__BYOK_JWT_TIERING_CONFIG__")));
      if (configuration.Properties().Count() != 4 || configuration["version"] == null
          || configuration["version"].Type != Newtonsoft.Json.Linq.JTokenType.Integer || (int)configuration["version"] != 1) { return "__invalid__"; }
      var tiers = configuration["tiers"] as Newtonsoft.Json.Linq.JArray;
      if (tiers == null || tiers.Count == 0 || tiers.Count > 8) { return "__invalid__"; }
      var tierNames = new System.Collections.Generic.List<string>();
      foreach (var tier in tiers) {
        if (tier.Type != Newtonsoft.Json.Linq.JTokenType.String
            || !System.Text.RegularExpressions.Regex.IsMatch((string)tier, @"\A[a-z][a-z0-9-]{0,79}\z")
            || tierNames.Contains((string)tier)) { return "__invalid__"; }
        tierNames.Add((string)tier);
      }
      foreach (var providerName in new[] { "entra", "okta" }) {
        var provider = configuration[providerName] as Newtonsoft.Json.Linq.JObject;
        if (provider == null || provider.Properties().Count() != 3 || provider["enabled"] == null
            || provider["enabled"].Type != Newtonsoft.Json.Linq.JTokenType.Boolean
            || provider["claimName"] == null || provider["claimName"].Type != Newtonsoft.Json.Linq.JTokenType.String) { return "__invalid__"; }
        var configuredClaim = (string)provider["claimName"];
        if (!System.Text.RegularExpressions.Regex.IsMatch(configuredClaim, @"\A[A-Za-z][A-Za-z0-9_.-]{0,63}\z")
            || (providerName == "entra" && configuredClaim != "roles")
            || new[] { "iss", "aud", "sub", "uid", "cid", "scp", "exp", "nbf", "iat", "jti", "azp", "tid", "oid", "idtyp" }.Contains(configuredClaim)) { return "__invalid__"; }
        var mappings = provider["mappings"] as Newtonsoft.Json.Linq.JArray;
        if (mappings == null || mappings.Count > 16 || ((bool)provider["enabled"] && mappings.Count == 0)) { return "__invalid__"; }
        var mappedClaims = new System.Collections.Generic.List<string>();
        foreach (var mappingToken in mappings) {
          var mapping = mappingToken as Newtonsoft.Json.Linq.JObject;
          if (mapping == null || mapping.Properties().Count() != 2 || mapping["claimValue"] == null
              || mapping["claimValue"].Type != Newtonsoft.Json.Linq.JTokenType.String
              || mapping["tier"] == null || mapping["tier"].Type != Newtonsoft.Json.Linq.JTokenType.String
              || !System.Text.RegularExpressions.Regex.IsMatch((string)mapping["claimValue"], @"\A[A-Za-z][A-Za-z0-9_.:-]{0,127}\z")
              || !tierNames.Contains((string)mapping["tier"]) || mappedClaims.Contains((string)mapping["claimValue"])) { return "__invalid__"; }
          mappedClaims.Add((string)mapping["claimValue"]);
        }
      }
      var selectedProvider = (Newtonsoft.Json.Linq.JObject)configuration[method == "entraJwt" ? "entra" : "okta"];
      if (!(bool)selectedProvider["enabled"]) { return "__flat__"; }
      var token = (Jwt)context.Variables["parsedJwt"];
      if (token.Issuer != (string)context.Variables["callerIssuer"]) { return "__invalid__"; }
      var claimName = (string)selectedProvider["claimName"];
      if (!token.Claims.ContainsKey(claimName) || token.Claims[claimName] == null || token.Claims[claimName].Length == 0
          || token.Claims[claimName].Length > 64) { return "__invalid__"; }
      var parts = ((string)context.Variables["byokJwtToken"]).Split('.');
      if (parts.Length != 3) { return "__invalid__"; }
      var encodedPayload = parts[1].Replace('-', '+').Replace('_', '/');
      encodedPayload = encodedPayload.PadRight(encodedPayload.Length + (4 - encodedPayload.Length % 4) % 4, '=');
      var payload = Newtonsoft.Json.Linq.JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(encodedPayload)));
      if ((string)payload["iss"] != token.Issuer) { return "__invalid__"; }
      var claim = payload[claimName];
      if (claim == null || (claim.Type != Newtonsoft.Json.Linq.JTokenType.Array
          && !(method == "oktaJwt" && claim.Type == Newtonsoft.Json.Linq.JTokenType.String))) { return "__invalid__"; }
      var values = claim.Type == Newtonsoft.Json.Linq.JTokenType.Array ? (Newtonsoft.Json.Linq.JArray)claim : new Newtonsoft.Json.Linq.JArray(claim);
      if (values.Count != token.Claims[claimName].Length) { return "__invalid__"; }
      var seen = new System.Collections.Generic.List<string>();
      var selectedTier = "";
      foreach (var value in values) {
        if (value.Type != Newtonsoft.Json.Linq.JTokenType.String || string.IsNullOrWhiteSpace((string)value)
            || ((string)value).Length > 128 || seen.Contains((string)value)
            || !token.Claims[claimName].Contains((string)value)) { return "__invalid__"; }
        seen.Add((string)value);
        foreach (var mapping in (Newtonsoft.Json.Linq.JArray)selectedProvider["mappings"]) {
          if ((string)mapping["claimValue"] != (string)value) { continue; }
          var mappedTier = (string)mapping["tier"];
          if (!string.IsNullOrEmpty(selectedTier) && selectedTier != mappedTier) { return "__invalid__"; }
          selectedTier = mappedTier;
        }
      }
      return string.IsNullOrEmpty(selectedTier) ? "__invalid__" : selectedTier;
    } catch { return "__invalid__"; }
  }
